mapper.select:
select d.TRADE_ID as tradeId, DATE_FORMAT(fin.EFF_DATE,'%Y-%m-%d') as effDate, fin.BASIS as basis, fin.YIELD as yield, d.INT_AMT as intAmt, if(@TRADE_ID=d.TRADE_ID,@rank:=@rank+1,@rank:=1) as num from trd_PRODUCT_DEAL d inner join FIN_PRODUCT zc on zc.finprod_id = d.finprod_id
left join TRD_PRODUCT_DEAL_ADD e on d.trade_id = e.trade_id left join TRD_TRADE_FEE_DETAIL tdf on tdf.trade_id = d.trade_id and tdf.fee_type = 'B09' left join (select * from FIN_CASH_CALC_RULE order by EFF_DATE) fin on fin.FINPROD_ID = d.FINPROD_ID , (select @d.TRADE_ID:=null,@rank:=0) b where 1=1
and d.TRADE_ID = #{tradeId}
